let map=null,layer=null;
try{if(window.L){map=L.map('route-map',{scrollWheelZoom:false}).setView([13.75,100.52],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:18}).addTo(map).on('tileerror',()=>{document.getElementById('route-map-status').textContent='部分底图未加载，可继续查看下方地点顺序与交通，并点击 Google 实际导航。连线仅示意游览顺序。'});layer=L.layerGroup().addTo(map);}}catch{document.getElementById('route-map-status').textContent='地图加载失败，下面的交通清单和 Google 导航仍可使用。'}
const tabs=document.getElementById('route-tabs');routes.forEach((r,i)=>{const b=document.createElement('button');b.textContent=r.label;b.type='button';b.setAttribute('aria-pressed',i===2?'true':'false');b.addEventListener('click',()=>renderRoute(i));tabs.append(b);});
function placeLink(id){const p=points[id];return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p[3])+(id==='hotel'?'&query_place_id=ChIJZ6FKAsaZ4jAR6ce7Af248KM':'');}
function renderRoute(index){const r=routes[index];[...tabs.children].forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));document.getElementById('route-summary').textContent=r.summary;const host=document.getElementById('route-stops');host.replaceChildren();if(layer)layer.clearLayers();const coords=r.ids.map(id=>points[id].slice(1,3));if(map){L.polyline(coords,{color:'#c78b25',weight:3,dashArray:'7 7'}).addTo(layer);r.ids.forEach((id,i)=>{const p=points[id];const content=document.createElement('div');const title=document.createElement('strong');title.textContent=(i+1)+'. '+p[0];const a=document.createElement('a');a.href=placeLink(id);a.target='_blank';a.rel='noreferrer';a.textContent='打开 Google 地图';content.append(title,document.createElement('br'),a);L.marker(p.slice(1,3),{icon:L.divIcon({className:'route-pin',html:String(i+1),iconSize:[30,30],iconAnchor:[15,15]})}).bindPopup(content).addTo(layer);});map.fitBounds(coords,{padding:[35,35],maxZoom:14});}
r.legs.forEach((leg,i)=>{const a=points[r.ids[i]],b=points[r.ids[i+1]];const row=document.createElement('div');row.className='route-leg';const head=document.createElement('strong');head.textContent=`${i+1} ${a[0]} → ${i+2} ${b[0]}`;const desc=document.createElement('span');desc.textContent=`${leg[0]} · ${leg[1]} · ${leg[2]}`;const nav=document.createElement('a');nav.target='_blank';nav.rel='noreferrer';nav.textContent=leg[3]?'实际导航 ↗':'查看目的地区域 ↗';nav.href=leg[3]?'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(a[3])+'&destination='+encodeURIComponent(b[3])+'&travelmode='+leg[3]:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b[3]);if(leg[3]&&r.ids[i]==='hotel')nav.href+='&origin_place_id=ChIJZ6FKAsaZ4jAR6ce7Af248KM';if(leg[3]&&r.ids[i+1]==='hotel')nav.href+='&destination_place_id=ChIJZ6FKAsaZ4jAR6ce7Af248KM';row.append(head,desc,nav);host.append(row);});}
